/* ISO type names are administratively precise but read coldly on a form.
   Soften the common ones; anything unmapped passes through unchanged. */
var TIDY={
  "Metropolitan region":"Region","Metropolitan department":"Department",
  "Metropolitan collectivity with special status":"Collectivity",
  "Overseas territorial collectivity":"Overseas collectivity",
  "Overseas departmental collectivity":"Overseas department",
  "Geographical region":"Region","Geographical entity":"Region","Geographical unit":"Region",
  "Administrative region":"Region","Autonomous region":"Region",
  "Special administrative region":"Region",
  "Administrative territory":"Territory","Federal district":"District",
  "Federal territory":"Territory","Federal capital territory":"Territory",
  "Capital city":"City","Capital District":"District","Capital territory":"Territory",
  "Metropolitan administration":"Metropolitan area",
  "Metropolitan city":"City","Municipality":"Municipality",
  "Unitary authority":"Council area","Two-tier county":"County",
  "London borough":"London borough","City corporation":"City",
  "Country":"Nation","State":"State","Province":"Province",
  "District council area":"District council","Council area":"Council area",
  "Special municipality":"Municipality","Rural municipality":"Municipality",
  "Special city":"City","Special island authority":"Island authority",
  "Popularate":"Governorate","Governorate":"Governorate",
  "Included for completeness":"Division"
};
function tidy(t){ if(!t) return t; return TIDY[t]||t; }

var cache={};
function subs(cc){
  if(!SUB[cc])return [];
  if(!cache[cc]) cache[cc]=SUB[cc].split("|").map(function(r){var p=r.split("~");return{code:p[0],name:p[1],type:p[2],parent:p[3]};});
  return cache[cc];
}
return {
  countries:CO,
  dialFor:function(cc){for(var i=0;i<CO.length;i++)if(CO[i].code===cc)return CO[i].dial;return "";},
  nameFor:function(cc){for(var i=0;i<CO.length;i++)if(CO[i].code===cc)return CO[i].name;return cc;},
  /* top-level divisions: states, provinces, regions, districts */
  primary:function(cc){return subs(cc).filter(function(s){return !s.parent;});},
  /* second-level divisions belonging to a chosen primary (e.g. French departments) */
  secondary:function(cc,parentCode){return subs(cc).filter(function(s){return s.parent===parentCode;});},
  /* local government areas where we hold a verified list */
  local:function(cc,primaryCode){var m=LGA[cc]&&LGA[cc][primaryCode];return m?m.split(","):null;},
  labelPrimary:function(cc){var s=this.primary(cc);if(!s.length)return "State or province";
    var t={},best="",n=0;s.forEach(function(x){t[x.type]=(t[x.type]||0)+1;if(t[x.type]>n){n=t[x.type];best=x.type;}});
    return tidy(best)||"State or province";},
  labelSecondary:function(cc,parentCode){var s=this.secondary(cc,parentCode);if(!s.length)return null;
    var t={},best="",n=0;s.forEach(function(x){t[x.type]=(t[x.type]||0)+1;if(t[x.type]>n){n=t[x.type];best=x.type;}});
    return tidy(best)||"District";}
};
